<script setup lang="ts">
import type { ApiProblem } from '~/types/api'; import type { AcademicTerm } from '~/types/domain'; import type { FormFieldDefinition } from '~/types/forms'
definePageMeta({ middleware: 'auth' })
const fields: FormFieldDefinition[] = [{ key: 'academic_year', label: 'Academic year', required: true, placeholder: '2026-2027' }, { key: 'term', label: 'Term', type: 'select', required: true, options: [{ label: 'First Semester', value: 'first_semester' }, { label: 'Second Semester', value: 'second_semester' }, { label: 'Summer', value: 'summer' }] }, { key: 'start_date', label: 'Start date', type: 'date', required: true }, { key: 'end_date', label: 'End date', type: 'date', required: true }, { key: 'status', label: 'Status', type: 'select', required: true, options: [{ label: 'Upcoming', value: 'upcoming' }, { label: 'Active', value: 'active' }, { label: 'Completed', value: 'completed' }] }]
const { create } = useAcademicTerms(); const { show } = useToasts(); const submitting = ref(false); const errors = ref<Record<string, string[]>>({})
async function save(values: Record<string, string | number>): Promise<void> { submitting.value = true; errors.value = {}; try { await create(values as unknown as Partial<AcademicTerm>); show('Academic term created successfully.'); await navigateTo('/academic-terms') } catch (error) { const problem = error as ApiProblem; errors.value = problem.errors ?? { form: [problem.message] } } finally { submitting.value = false } }
</script>
<template><div class="page-shell"><PageHeader title="Add academic term" description="Define a new period in the academic calendar." /><EntityForm :fields="fields" submit-label="Create term" cancel-to="/academic-terms" :submitting="submitting" :server-errors="errors" @submit="save" /></div></template>
